export const translations = { en, fr, es, he };

export function translate(language:SupportedLanguage,key:TranslationKey,vars?:Record<string,string|number>):string {
  const dict=translations[language] ?? translations.en;
  let value=(dict[key] ?? translations.en[key] ?? key) as string;
  if(vars) for(const [name,replacement] of Object.entries(vars)) value=value.replace(new RegExp(`{{${name}}}`,'g'),String(replacement));
  return value;
}
